        const unevaluable = sourceExclusionOutcomeIsUnevaluable(decision.outcome);
        if (decision.excluded) {
          excluded.items += 1;
          if (unevaluable)
            excluded.unevaluable += 1;
          continue;
        }
        if (decision.disposition !== "metadata_only" || !row.hasContent)
          continue;
